<?php declare(strict_types=1);echo$view->render('components.page-hero',compact('page','e'));?><section class="section"><div class="container-wide"><h2>Professional resources</h2><div class="feature-grid feature-grid-three"><?php foreach($library['resources']as$r):?><article class="feature-card"><h3><?= $e($r['title']) ?></h3><p><?= $e($r['excerpt']??'') ?></p><a href="/resources/<?= rawurlencode($r['slug']) ?>">Read resource</a></article><?php endforeach;?></div><h2>Downloads</h2><?php foreach($library['downloads']as$d):?><p><a href="/downloads/<?= rawurlencode($d['slug']) ?>"><?= $e($d['title']) ?></a> <small><?= $e($d['mime_type']) ?></small></p><?php endforeach;?><h2>Frequently asked questions</h2><?php foreach($library['faqs']as$f):?><details><summary><?= $e($f['question']) ?></summary><p><?= nl2br($e($f['answer_text'])) ?></p></details><?php endforeach;?><?php if($library['resources']===[]&&$library['downloads']===[]&&$library['faqs']===[]):?><div class="empty-state"><p>No published resources are currently available.</p></div><?php endif;?></div></section>
